<script>(()=>{const modal=document.getElementById('document-preview'),frame=document.getElementById('document-preview-frame'),download=document.getElementById('document-preview-download');document.querySelectorAll('a[href$="/pdf"]').forEach(link=>{const preview=document.createElement('button');preview.type='button';preview.className='tiny-button';preview.textContent='Preview';preview.addEventListener('click',()=>{frame.src=link.href.replace(/\/pdf$/, '/preview');download.href=link.href;document.getElementById('document-preview-title').textContent='Preview '+link.closest('tr').querySelector('td').textContent.trim();modal.classList.remove('hidden')});link.parentNode.insertBefore(preview,link)});const close=()=>{modal.classList.add('hidden');frame.src=''};document.getElementById('close-document-preview').addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()});document.getElementById('print-document-preview').addEventListener('click',()=>{if(frame.contentWindow)frame.contentWindow.print()})})();</script>
